IF bReset OR NOT bEnable THEN
    rPhaseAcc := 0.0;
    rTarget := rPMin;
    rTargetPrev := rPMin;
    rTargetLast := rPMin;
    rTargetLead := rPMin;
    rTargetLeadPrev := rPMin;
    rTargetLeadLast := rPMin;
    bNewCycle := FALSE;
    bFirstRun := TRUE;
    iIdxCounter := 0;
    RETURN;
END_IF

// 频率保护
IF rFrequency < 0.01 THEN
    rTarget := rPMin;
    rTargetPrev := rPMin;
    RETURN;
END_IF

// 计算每周期采样点数
// 【每周期采样点数的物理含义】
// iPointsPerCycle = 1 / (f * dt) 表示一个完整波形周期被分成多少个采样点。
// 例如 f=1Hz, dt=1ms → iPointsPerCycle = 1000 点/周期。
// 点数太少会导致波形分辨率不足（如方波变成阶梯），
// 所以设下限 10 点保证基本波形质量。
iPointsPerCycle := REAL_TO_INT(1.0 / (rFrequency * rDt));
IF iPointsPerCycle < 10 THEN
    iPointsPerCycle := 10;
END_IF

// 保存上一步值
rTargetPrev := rTargetLast;

// 相位推进
// 【相位累加器机制】
// rPhaseAcc 是一个 0~1 的循环累加器，表示"当前在一个波形周期内的位置"。
// 每个扫描周期，相位增加 Δφ = f * dt:
//   - f=1Hz, dt=1ms → Δφ = 0.001，一个周期 1000 步走完 0→1
//   - f=5Hz, dt=1ms → Δφ = 0.005，一个周期 200 步走完
//
// rPhaseAcc 代表"归一化时间"，0=周期起点，1=周期终点。
// 相位与物理时间的对应: t = φ / f（秒）
//
// 使用累加器而非直接计时的原因:
//   (1) 避免浮点累积误差: 如果用 t = t + dt 然后取模，
//       长时间运行后 t 的浮点精度会下降（大数+小数）
//   (2) 相位本身是 [0,1) 的小数，累积误差可控
//   (3) 过零检测简单: rPhaseAcc >= 1.0 时减 1 即可
//
rPhaseAcc := rPhaseAcc + rFrequency * rDt;

// 检测新周期
IF rPhaseAcc >= 1.0 THEN
    // 相位超出 [0,1) 范围，回卷到 [0,1)
    // 注意: rPhaseAcc - 1.0 而非直接置零，保留小数部分避免相位跳变
    // 例如: rPhaseAcc = 1.003 → 修正后 = 0.003，保留了超出的 0.003 周期
    rPhaseAcc := rPhaseAcc - 1.0;
    bNewCycle := TRUE;
    iIdxCounter := 0;
ELSE
    bNewCycle := FALSE;
END_IF

rPhase := rPhaseAcc;
iPointIndex := iIdxCounter;

// ============================================================
// 波形计算
// ============================================================
CASE iWaveType OF

0:  // 正弦波 (-cos型，从PMin起步平滑上升)
    // 【为什么使用 -cos 形式从 PMin 平滑起步】
    // 标准正弦 sin(2πφ) 在 φ=0 时值为 0，对应中点 (PMax+PMin)/2，
    // 且 φ=0 处导数最大 → 压力一开机就急速上升，不利于平稳启动。
    //
    // -cos(2πφ) 在 φ=0 时值为 -1：
    //   P(φ) = (PMax+PMin)/2 - (PMax-PMin)/2 * (-1) = PMin
    //   从最低压力 PMin 起步，符合"从谷值开始"的物理要求。
    //
    // 更关键的优点: -cos 在 φ=0 处导数 dP/dφ = 0，
    //   即压力在周期起点处变化率为零 → 平滑上升，
    //   不会在波形起始处产生突变的 dP/dt（目标压力变化率），
    //   前馈控制器不需要在起始瞬间提供极大的电压。
    //   对比 sin: sin(0)=0 但 dP/dφ = PMax-PMin（最大速率），
    //   起始就有大的 dP/dt，前馈和执行机构承受冲击。
    //
    rTarget := (rPMax + rPMin) / 2.0
               - (rPMax - rPMin) / 2.0 * COS(2.0 * PI * rPhase);

1:  // 方波 (带过渡段)
    // 【方波过渡段的目的——避免不连续性】
    // 理想方波在 PMin 和 PMax 之间瞬间跳变，
    // dP/dt 在跳变点为无穷大，现实中执行器无法跟踪。
    // 更严重的是: dP/dt = ±∞ 会导致模型前馈 u_ff → ∞，
    // 控制电压瞬间饱和，系统和执行器承受巨大冲击。
    //
    // 过渡段 (RISE_RATIO_SQUARE = 8% 周期) 的作用:
    //   - 在 PMin→PMax 和 PMax→PMin 的跳变处插入线性过渡，
    //     将 dP/dt 限制在 (PMax-PMin) / (过渡段时长) 的有限值
    //   - 过渡段时长 = 0.08 / f，例如 f=1Hz 时 = 80ms
    //   - 虽然仍有 dP/dt 的阶跃变化（恒斜率），但幅值有限可跟踪
    //
    // 四段划分:
    //   0% ~ 8%:   线性上升 (PMin → PMax)
    //   8% ~ 50%:  高位保持 (PMax)
    //   50% ~ 58%: 线性下降 (PMax → PMin)
    //   58% ~ 100%: 低位保持 (PMin)
    //
    IF rPhase < RISE_RATIO_SQUARE THEN
        rTarget := rPMin + (rPMax - rPMin) * (rPhase / RISE_RATIO_SQUARE);
    ELSIF rPhase < 0.5 THEN
        rTarget := rPMax;
    ELSIF rPhase < (0.5 + RISE_RATIO_SQUARE) THEN
        rTarget := rPMax - (rPMax - rPMin) * ((rPhase - 0.5) / RISE_RATIO_SQUARE);
    ELSE
        rTarget := rPMin;
    END_IF

2:  // 三角波
    // 三角波是最简单的分段线性波形，两段等长:
    //   0% ~ 50%:  线性上升 (PMin → PMax)
    //   50% ~ 100%: 线性下降 (PMax → PMin)
    // dP/dt 在过零点有阶跃变化（斜率切换），但幅值恒定有限。
    IF rPhase < 0.5 THEN
        rTarget := rPMin + (rPMax - rPMin) * (rPhase / 0.5);
    ELSE
        rTarget := rPMax - (rPMax - rPMin) * ((rPhase - 0.5) / 0.5);
    END_IF

3:  // 梯形波
    // 【梯形波分段计算】
    // 梯形波是方波的平滑版本，四段组成:
    //   rR% 上升段: PMin 线性升至 PMax
    //   rH% 保持段: 停留在 PMax
    //   rF% 下降段: PMax 线性降至 PMin
    //   rL% 低保持段: 停留在 PMin
    //   （rL = 1 - rR - rH - rF，自动计算）
    //
    // 各段的相位区间:
    //   [0, rR):         上升
    //   [rR, rR+rH):     高位保持
    //   [rR+rH, rR+rH+rF): 下降
    //   [rR+rH+rF, 1.0): 低位保持
    //
    // 参数保护: 若用户设 rR/rH/rF < 0.01（如未配置），
    // 则回退到默认值，防止零宽度段导致除零。
    // 总占比检查: 若 rR+rH+rF > 1.0，则 rL=0，梯形波退化为三角波。
    //
    rR := rRisePct;
    rH := rHoldPct;
    rF := rFallPct;
    IF rR < 0.01 THEN rR := 0.1; END_IF
    IF rH < 0.01 THEN rH := 0.3; END_IF
    IF rF < 0.01 THEN rF := 0.1; END_IF
    rL := 1.0 - rR - rH - rF;
    IF rL < 0.0 THEN rL := 0.0; END_IF

    IF rPhase < rR THEN
        // 上升段: P = PMin + (PMax-PMin) * (φ / rR)
        // 斜率 = (PMax-PMin) / rR / T，其中T为周期
        rTarget := rPMin + (rPMax - rPMin) * (rPhase / rR);
    ELSIF rPhase < (rR + rH) THEN
        rTarget := rPMax;
    ELSIF rPhase < (rR + rH + rF) THEN
        // 下降段: P = PMax - (PMax-PMin) * ((φ-rR-rH) / rF)
        rTarget := rPMax - (rPMax - rPMin) * ((rPhase - rR - rH) / rF);
    ELSE
        rTarget := rPMin;
    END_IF

4:  // ★ 自定义波形 — 查表 + 线性插值
    LutInterpolate();

ELSE
    // 默认正弦
    rTarget := (rPMax + rPMin) / 2.0
               - (rPMax - rPMin) / 2.0 * COS(2.0 * PI * rPhase);
END_CASE

// 限幅保护
IF rTarget < 0.0 THEN rTarget := 0.0; END_IF
IF rTarget > 50.0 THEN rTarget := 50.0; END_IF

// 【首次运行初始化——防止 rTargetPrev 不匹配】
// 第一个扫描周期时，rTargetPrev 还没有被赋值（初始为 rPMin），
// 而 rTarget 已经根据波形计算出了值。如果两者不一致，
// 外部用 (rTarget - rTargetPrev)/dt 计算的 dP/dt 会产生巨大的伪微分值。
// 因此首次运行时令 rTargetPrev := rTarget，确保 dP/dt = 0 起步。
IF bFirstRun THEN
    rTargetPrev := rTarget;
    rTargetLeadPrev := rTargetLead;
    bFirstRun := FALSE;
END_IF

rTargetLast := rTarget;
// ============================================================
// MFF超前目标计算
// ============================================================
// 在当前相位基础上加超前相位偏移，计算"未来N步"的目标值
// MFF使用超前目标可以提前输出控制量，补偿系统滞后
// 超前相位 = nMffLeadSteps × f × dt (归一化到0~1)
//
rTargetLeadPrev := rTargetLeadLast;

IF nMffLeadSteps > 0 THEN
    rPhaseLead := rPhaseAcc + INT_TO_REAL(nMffLeadSteps) * rFrequency * rDt;
    // 循环回卷到 [0, 1)
    IF rPhaseLead >= 1.0 THEN
        rPhaseLead := rPhaseLead - 1.0;
    END_IF

    // 用超前相位计算目标值(与主波形相同的公式)
    CASE iWaveType OF
    0:  // 正弦波
        rTargetLead := (rPMax + rPMin) / 2.0
                       - (rPMax - rPMin) / 2.0 * COS(2.0 * PI * rPhaseLead);
    1:  // 方波
        IF rPhaseLead < RISE_RATIO_SQUARE THEN
            rTargetLead := rPMin + (rPMax - rPMin) * (rPhaseLead / RISE_RATIO_SQUARE);
        ELSIF rPhaseLead < 0.5 THEN
            rTargetLead := rPMax;
        ELSIF rPhaseLead < (0.5 + RISE_RATIO_SQUARE) THEN
            rTargetLead := rPMax - (rPMax - rPMin) * ((rPhaseLead - 0.5) / RISE_RATIO_SQUARE);
        ELSE
            rTargetLead := rPMin;
        END_IF
    2:  // 三角波
        IF rPhaseLead < 0.5 THEN
            rTargetLead := rPMin + (rPMax - rPMin) * (rPhaseLead / 0.5);
        ELSE
            rTargetLead := rPMax - (rPMax - rPMin) * ((rPhaseLead - 0.5) / 0.5);
        END_IF
    3:  // 梯形波
        IF rPhaseLead < rR THEN
            rTargetLead := rPMin + (rPMax - rPMin) * (rPhaseLead / rR);
        ELSIF rPhaseLead < (rR + rH) THEN
            rTargetLead := rPMax;
        ELSIF rPhaseLead < (rR + rH + rF) THEN
            rTargetLead := rPMax - (rPMax - rPMin) * ((rPhaseLead - rR - rH) / rF);
        ELSE
            rTargetLead := rPMin;
        END_IF
    4:  // 自定义波形LUT插值
        IF bLutValid AND iLutLen >= 2 THEN
            rTargetLead := LutInterpolateAtPhase(rPhaseLead);
        ELSE
            rTargetLead := (rPMax + rPMin) / 2.0
                           - (rPMax - rPMin) / 2.0 * COS(2.0 * PI * rPhaseLead);
        END_IF
    ELSE
        rTargetLead := (rPMax + rPMin) / 2.0
                       - (rPMax - rPMin) / 2.0 * COS(2.0 * PI * rPhaseLead);
    END_CASE

    IF rTargetLead < 0.0 THEN rTargetLead := 0.0; END_IF
    IF rTargetLead > 50.0 THEN rTargetLead := 50.0; END_IF
ELSE
    // 无超前，等于当前目标
    rTargetLead := rTarget;
END_IF

rTargetLeadLast := rTargetLead;

iIdxCounter := iIdxCounter + 1;


// ============================================================
// 自定义波形: LUT线性插值
// ============================================================
// LUT 存储一个完整周期的压力值 (MPa)，等间距分布
// 相位 0~1 映射到索引 0~(N-1)，相邻两点线性插值
//
// 例: N=2000, phase=0.333
//   连续索引 = 0.333 * 1999 = 665.667
//   idx0 = 665, idx1 = 666
//   frac = 0.667
//   output = LUT[665] * 0.333 + LUT[666] * 0.667
// ============================================================

IF NOT bLutValid OR iLutLen < 2 THEN
    rTarget := (rPMax + rPMin) / 2.0
               - (rPMax - rPMin) / 2.0 * COS(2.0 * PI * rPhase);
    RETURN;
END_IF

nPts := iLutLen;
IF nPts > MAX_LUT_POINTS THEN nPts := MAX_LUT_POINTS; END_IF

// 相位 → 连续索引
// 【LUT 插值算法详解】
// LUT 存储了 N 个等间距采样点，覆盖一个完整周期 [0, 1)。
// 相位 φ ∈ [0, 1) 映射到连续索引 idx ∈ [0, N-1]:
//   rContIdx = φ * (N - 1)
//
// 为什么用 N-1 而不是 N:
//   φ=0 → idx=0 (第一个点)
//   φ=1⁻ → idx→(N-1) (最后一个点)
//   如果用 N，则 φ=1⁻ → idx→N，超出数组上界，造成越界。
//   用 N-1 保证首末两端精确对应，且相位在 [0,1) 内索引不会越界。
//
rContIdx := rPhase * INT_TO_REAL(nPts - 1);

// 分离整数和小数部分 (TRUNC 向零截断，对正数等价于向下取整)
// 【为什么需要 TRUNC + 范围检查】
// TRUNC 向零截断: TRUNC(3.7) = 3, TRUNC(-0.5) = 0
// 对于正数 rContIdx，TRUNC 等价于 FLOOR（向下取整）。
// 但有两个风险需要范围检查:
//
// (1) rPhase 浮点误差可能导致 rContIdx 略超出 [0, N-1]:
//     例如 rPhase = 1.0（理论上不应出现，但浮点累积误差可能产生），
//     则 rContIdx = N-1，此时 iIdx0 = N-1，iIdx1 = N 越界。
//     所以需要检查 iIdx0 >= nPts-1 时直接返回末尾值。
//
// (2) 极端情况下 rPhase 可能为负数（浮点误差或复位时序问题），
//     TRUNC 对负数向零截断不等于 FLOOR，例如 TRUNC(-0.1) = 0，
//     而 FLOOR(-0.1) = -1。代码检查 iIdx0 < 0 时钳位到 0，
//     防止数组负索引越界。
//
// 综上，TRUNC+范围检查 = 安全的整数索引提取，
// 保证 iIdx0 ∈ [0, nPts-2]（正常插值区间），
// 边界情况 iIdx0 ≥ nPts-1 时直接返回 arrLUT[nPts-1]。
//
iIdx0 := REAL_TO_INT(TRUNC(rContIdx));
IF iIdx0 < 0 THEN iIdx0 := 0; END_IF
IF iIdx0 >= nPts - 1 THEN
    // 到达末尾，直接取最后一个点
    rTarget := arrLUT[nPts - 1];
    RETURN;
END_IF

iIdx1 := iIdx0 + 1;
rFrac := rContIdx - INT_TO_REAL(iIdx0);

// 线性插值: y = y0*(1-f) + y1*f
// 【线性插值原理】
// 在 LUT[iIdx0] 和 LUT[iIdx1] 之间做线性内插:
//   rTarget = arrLUT[iIdx0] * (1.0 - rFrac) + arrLUT[iIdx1] * rFrac
//
// rFrac ∈ [0, 1) 表示当前相位在两采样点之间的相对位置:
//   rFrac = 0 → 正好在 iIdx0 点，取 arrLUT[iIdx0]
//   rFrac = 0.5 → 两点中点，取平均值
//   rFrac → 1⁻ → 接近 iIdx1 点
//
// 这种插值的精度取决于 LUT 点数:
//   N=2000 点/周期，正弦波最大插值误差 ≈ (π/N)² * Peak/8 ≈ 0.0002%，
//   远小于系统其他误差源，完全可以忽略。
//
rTarget := arrLUT[iIdx0] * (1.0 - rFrac) + arrLUT[iIdx1] * rFrac;

n := nPoints;
IF n < 2 THEN n := 2; END_IF
IF n > MAX_LUT_POINTS THEN n := MAX_LUT_POINTS; END_IF

// 复制数据到内部 LUT
FOR i := 0 TO n - 1 DO
    arrLUT[i] := pData[i];
END_FOR

iLutLen := n;
bLutValid := TRUE;

IF NOT bLutValid OR iLutLen < 2 THEN
    LutInterpolateAtPhase := (rPMax + rPMin) / 2.0
                             - (rPMax - rPMin) / 2.0 * COS(2.0 * PI * rPhaseIn);
    RETURN;
END_IF

nPts := iLutLen;
IF nPts > MAX_LUT_POINTS THEN nPts := MAX_LUT_POINTS; END_IF

rContIdx := rPhaseIn * INT_TO_REAL(nPts - 1);
iIdx0 := REAL_TO_INT(TRUNC(rContIdx));
IF iIdx0 < 0 THEN iIdx0 := 0; END_IF
IF iIdx0 >= nPts - 1 THEN
    LutInterpolateAtPhase := arrLUT[nPts - 1];
    RETURN;
END_IF

iIdx1 := iIdx0 + 1;
rFrac := rContIdx - INT_TO_REAL(iIdx0);
LutInterpolateAtPhase := arrLUT[iIdx0] * (1.0 - rFrac) + arrLUT[iIdx1] * rFrac;

// ============================================================
// 主计算
// ============================================================

// 复位
IF bReset OR NOT bEnable THEN
    // ADRC 状态复位
    z1 := 0.0;
    z2 := 0.0;
    rUfbPrev := 0.0;
    // PID 状态复位
    rIntegral := 0.0;
    rDfilt := 0.0;
    rErrorPrev := 0.0;
    rOutputRaw := 0.0;
    // 输出清零
    rOutput := 0.0;
    rZ1 := 0.0;
    rZ2 := 0.0;
    rPID_P := 0.0;
    rPID_I := 0.0;
    rPID_D := 0.0;
    IF NOT bEnable THEN
        bInitialized := FALSE;
    END_IF
    RETURN;
END_IF

// 参数保护
IF rDt < 1.0E-6 THEN
    rOutput := 0.0;
    RETURN;
END_IF

// ============================================================
// 根据 nCtrlMode 选择控制算法
// ============================================================

IF nCtrlMode = 1 THEN
    // ============================================================
    // 经典 PID 控制器
    // ============================================================
    // 控制律: u = Kp*e + Ki*∫e*dt + Kd*de/dt(filtered)
    //
    // 微分项使用一阶低通滤波避免噪声放大:
    //   D_filt(k) = D_filt(k-1) + (dt/Tf) * (Kd*(e-e_prev)/dt - D_filt(k-1))
    //            = (1 - dt/Tf)*D_filt(k-1) + (Kd/Tf)*(e - e_prev)
    //   当 Tf → 0 时退化为纯微分
    //
    // 积分抗饱和 (back-calculation):
    //   当输出饱和时，用饱和误差反馈修正积分项:
    //   ∫e += (e + Kb*(u_sat - u_raw)) * dt
    //   Kb 越大，抗饱和越快
    //
    // ============================================================

    // --- 比例项 ---
    rPID_P := rPID_Kp * rError;

    // --- 微分项 (带滤波) ---
    IF rPID_Tf > rDt THEN
        // 一阶滤波微分
        rDfilt := rDfilt + (rDt / rPID_Tf) * (rPID_Kd * (rError - rErrorPrev) / rDt - rDfilt);
    ELSE
        // Tf 太小，直接用差分
        rDfilt := rPID_Kd * (rError - rErrorPrev) / rDt;
    END_IF
    rPID_D := rDfilt;

    // --- 积分项 (带抗饱和) ---
    // 使用 back-calculation: 积分输入 = e + Kb*(u_saturated - u_raw)
    rIntegral := rIntegral + rPID_Ki * (rError + rPID_Kb * (rOutput - rOutputRaw)) * rDt;

    // 积分限幅 (防止极端情况)
    IF rIntegral > OUTPUT_LIMIT THEN rIntegral := OUTPUT_LIMIT; END_IF
    IF rIntegral < -OUTPUT_LIMIT THEN rIntegral := -OUTPUT_LIMIT; END_IF
    rPID_I := rIntegral;

    // --- 合成输出 ---
    rOutputRaw := rPID_P + rPID_I + rPID_D;

    // --- 输出限幅 ---
    rUfb := rOutputRaw;
    IF rUfb > OUTPUT_LIMIT THEN rUfb := OUTPUT_LIMIT; END_IF
    IF rUfb < -OUTPUT_LIMIT THEN rUfb := -OUTPUT_LIMIT; END_IF

    rOutput := rUfb;

    // 保存上一步误差
    rErrorPrev := rError;

    // ADRC 诊断输出清零
    rZ1 := 0.0;
    rZ2 := 0.0;
    rOmegaC := 0.0;
    rB0 := 0.0;

ELSE
    // ============================================================
    // ADRC 控制器 (默认模式, nCtrlMode = 0)
    // ============================================================

    // 额外参数保护 (ADRC 需要容积和弹性模量)
    IF rVTotal < 1.0E-8 OR rBetaE < 1.0E6 THEN
        rOutput := 0.0;
        RETURN;
    END_IF

    // 从阀样本参数反推 Kv (与 FB_ModelFeedforward 相同的公式)
    IF rValveQnom > 0.1 AND rValveDPnom > 0.1 AND rValveUmax > 0.1 THEN
        rKv := (rValveQnom / 60000.0) / (rValveUmax * SQRT(rValveDPnom * 1.0E5));
    ELSE
        rKv := 8.91E-8;
    END_IF

    IF rKv < 1.0E-15 THEN
        rOutput := 0.0;
        RETURN;
    END_IF

    // ============================================================
    // 计算标称增益 b0 (首次或参数变化时)
    // b0 = (βe / V_total) * Kv * √(Ps/2) / 1e6   [MPa/s/V]
    // ============================================================
    IF NOT bInitialized THEN
        rB0Base := (rBetaE / rVTotal) * rKv * SQRT(rPs / 2.0) / 1.0E6;
        bInitialized := TRUE;
    END_IF

    // ============================================================
    // 容积自适应带宽
    // ============================================================
    rAlpha := rVRef / rVTotal;
    // 限幅
    IF rAlpha < 0.15 THEN rAlpha := 0.15; END_IF
    IF rAlpha > 5.0 THEN rAlpha := 5.0; END_IF

    // ωc = ωc_base * α^0.5,  ωo = ωo_base * α^0.4
    rOmegaC := rOmegaCBase * SQRT(rAlpha);
    rOmegaO := rOmegaOBase * EXP(0.4 * LN(rAlpha));

    // b0 不随容积缩放 — 初始化时已按实际容积计算
    rB0 := rB0Base;

    // ============================================================
    // ESO 增益 (带宽参数化)
    // β1 = 2*ωo,  β2 = ωo²
    // ============================================================
    rBeta1 := 2.0 * rOmegaO;
    rBeta2 := rOmegaO * rOmegaO;

    // ============================================================
    // ESO 观测更新 (欧拉积分)
    // dz1/dt = z2 + β1*(e - z1) - b0*u_fb_prev
    // dz2/dt = β2*(e - z1)
    // ============================================================
    rEobs := rError - z1;

    z1 := z1 + (z2 + rBeta1 * rEobs - rB0 * rUfbPrev) * rDt;
    z2 := z2 + (rBeta2 * rEobs) * rDt;

    // ============================================================
    // 控制律: u_fb = (kp * z1 + z2) / b0
    // 目标: de/dt = -ωc * e  (误差指数衰减)
    // ============================================================
    rKp := rOmegaC;

    IF ABS(rB0) > 1.0E-6 THEN
        rUfb := (rKp * z1 + z2) / rB0;
    ELSE
        rUfb := 0.0;
    END_IF

    // 输出限幅
    IF rUfb > OUTPUT_LIMIT THEN rUfb := OUTPUT_LIMIT; END_IF
    IF rUfb < -OUTPUT_LIMIT THEN rUfb := -OUTPUT_LIMIT; END_IF

    rOutput := rUfb;
    rUfbPrev := rUfb;

    // 诊断输出
    rZ1 := z1;
    rZ2 := z2;

    // PID 诊断输出清零
    rPID_P := 0.0;
    rPID_I := 0.0;
    rPID_D := 0.0;

END_IF

CASE Channel OF
	0:
	HighSpeedChannel := PWmotion.fpgadata.AD.AD_Volt[0];
	1:
	HighSpeedChannel := PWmotion.fpgadata.AD.AD_Volt[1];	
	2:
	HighSpeedChannel := PWmotion.fpgadata.AD.AD_Volt[2];
	3:
	HighSpeedChannel := PWmotion.fpgadata.AD.AD_Volt[3];
	4:
	HighSpeedChannel := PWmotion.fpgadata.AD.AD_Volt[4];
	5:
	HighSpeedChannel := PWmotion.fpgadata.AD.AD_Volt[5];	
	6:
	HighSpeedChannel := PWmotion.fpgadata.AD.AD_Volt[6];
	7:
	HighSpeedChannel := PWmotion.fpgadata.AD.AD_Volt[7];
	8:
	HighSpeedChannel := Axis.Pos_KP;
	9:
	HighSpeedChannel := Axis.Pos_Ki;	
	10:
	HighSpeedChannel := Axis.Pos_VelocityFFCoefficient;		
	11:
	HighSpeedChannel := Axis.Pos_VelocityFWCoefficient;		
	12:
	HighSpeedChannel := Axis.Pressure_KP;
	13:
	HighSpeedChannel := Axis.Pressure_Ki;	
	14:
	HighSpeedChannel := Axis.Force_KP;		
	15:
	HighSpeedChannel := Axis.Force_Ki;		
	16:
	HighSpeedChannel := Axis.Force_VelocityFFCoefficient;
	17:
	HighSpeedChannel := Axis.Force_ForceFFCoefficient;	
	18:
	HighSpeedChannel := Axis.Force_VelocityFWCoefficient;		
	19:
	HighSpeedChannel := Axis.PIDout;		
	20:
	HighSpeedChannel := Axis.PositionCMD;		
	21:
	HighSpeedChannel := Axis.PressureCMD;		
	22:
	HighSpeedChannel := Axis.ForceCMD;
	23:
	HighSpeedChannel := Axis.PositionError;	
	24:
	HighSpeedChannel := Axis.PressureError;		
	25:
	HighSpeedChannel := Axis.ForceError;	


END_CASE

IF bReset OR NOT bEnable THEN
    IF bReset THEN
        FOR iClrIdx := 0 TO 19 DO
            arrScale[iClrIdx] := 1.0;
            arrBinSum[iClrIdx] := 0.0;
            arrBinCount[iClrIdx] := 0;
        END_FOR
        iIterCount := 0;
        rRmsError := 0.0;
        bConverged := FALSE;
        rMidpoint := 0.0;
        rHalfRange := 0.0;
        rPrevActualMax := 0.0;
        rPrevActualMin := 0.0;
        rPrevActualRange := 0.0;
        rPrevTargetMax := 0.0;
        rPrevTargetMin := 0.0;
        rPrevTargetRange := 0.0;
    END_IF
    rOutput := 0.0;
    rVirtualTarget := 0.0;
    rTargetMax := -1.0E30;
    rTargetMin := 1.0E30;
    rActualMax := -1.0E30;
    rActualMin := 1.0E30;
    rErrorSum2 := 0.0;
    iErrorCount := 0;
    bNewCyclePrev := FALSE;
    IF NOT bEnable THEN
        RETURN;
    END_IF
END_IF

IF iPointsPerCycle < 10 THEN
    rOutput := 0.0;
    rVirtualTarget := 0.0;
    RETURN;
END_IF

// ============================================================
// 新周期：更新缩放系数 + 保存峰谷
// ============================================================
IF bNewCycle AND NOT bNewCyclePrev THEN
    IF iErrorCount > 0 THEN
        rRmsError := SQRT(rErrorSum2 / INT_TO_REAL(iErrorCount));
    END_IF
    rErrorSum2 := 0.0;
    iErrorCount := 0;

    // 诊断
    rPeakError := rTargetMax - rActualMax;
    rValleyError := rTargetMin - rActualMin;

    IF iIterCount > 0 THEN
        IF iMaxIterations > 0 AND iIterCount >= iMaxIterations THEN
            bConverged := TRUE;
        ELSE
            // 逐段更新缩放系数
            // 上半段(bin >= NUM_BINS/2): ampErr正 = 不够高 → scale增大
            // 下半段(bin < NUM_BINS/2): ampErr负 = 谷值太高 → 需scale增大来推低
            //   但 (target-mid) 是负数，scale增大让结果更负→更低，所以下半段取反
            FOR iBin := 0 TO NUM_BINS - 1 DO
                IF arrBinCount[iBin] > 2 THEN
                    rAvgErr := arrBinSum[iBin] / INT_TO_REAL(arrBinCount[iBin]);
                    IF rHalfRange > 0.001 THEN
                        IF iBin >= (NUM_BINS / 2) THEN
                            arrScale[iBin] := arrScale[iBin] + rLearningRate * rAvgErr / rHalfRange;
                        ELSE
                            arrScale[iBin] := arrScale[iBin] - rLearningRate * rAvgErr / rHalfRange;
                        END_IF
                    END_IF
                    IF arrScale[iBin] < SCALE_MIN THEN arrScale[iBin] := SCALE_MIN; END_IF
                    IF arrScale[iBin] > SCALE_MAX THEN arrScale[iBin] := SCALE_MAX; END_IF
                END_IF
            END_FOR
        END_IF
    END_IF

    // 保存本周期峰谷给下周期用（构建虚拟指令）
    rPrevActualMax := rActualMax;
    rPrevActualMin := rActualMin;
    rPrevActualRange := rActualMax - rActualMin;
    rPrevTargetMax := rTargetMax;
    rPrevTargetMin := rTargetMin;
    rPrevTargetRange := rTargetMax - rTargetMin;

    // 更新目标中点和半幅
    rMidpoint := (rTargetMax + rTargetMin) / 2.0;
    rHalfRange := (rTargetMax - rTargetMin) / 2.0;
    IF rHalfRange < 0.001 THEN rHalfRange := 0.001; END_IF

    // 重置
    FOR iClrIdx := 0 TO 19 DO
        arrBinSum[iClrIdx] := 0.0;
        arrBinCount[iClrIdx] := 0;
    END_FOR
    rTargetMax := -1.0E30;
    rTargetMin := 1.0E30;
    rActualMax := -1.0E30;
    rActualMin := 1.0E30;

    iIterCount := iIterCount + 1;
    iIteration := iIterCount;
END_IF

// ============================================================
// 每个采样点
// ============================================================
// 跟踪峰谷
IF rTargetRaw > rTargetMax THEN rTargetMax := rTargetRaw; END_IF
IF rTargetRaw < rTargetMin THEN rTargetMin := rTargetRaw; END_IF
IF rActual > rActualMax THEN rActualMax := rActual; END_IF
IF rActual < rActualMin THEN rActualMin := rActual; END_IF

// RMS
rErrorSum2 := rErrorSum2 + (rTargetRaw - rActual) * (rTargetRaw - rActual);
iErrorCount := iErrorCount + 1;

// ---- 学习：构建虚拟指令（从反馈缩放到目标范围）→ 纯幅值误差 ----
// 虚拟指令和反馈天然同相，误差不含相位分量
IF rPrevActualRange > 0.001 THEN
    // 反馈归一化到 [0,1]
    rNorm := (rActual - rPrevActualMin) / rPrevActualRange;
    IF rNorm < 0.0 THEN rNorm := 0.0; END_IF
    IF rNorm > 1.0 THEN rNorm := 1.0; END_IF

    // 虚拟指令 = 用目标的幅值范围重建
    rVT := rPrevTargetMin + rNorm * rPrevTargetRange;

    // 纯幅值误差
    rAmpErr := rVT - rActual;

    // 按反馈归一化位置索引 bin
    iBin := REAL_TO_INT(rNorm * INT_TO_REAL(NUM_BINS - 1));
    IF iBin < 0 THEN iBin := 0; END_IF
    IF iBin > NUM_BINS - 1 THEN iBin := NUM_BINS - 1; END_IF

    arrBinSum[iBin] := arrBinSum[iBin] + rAmpErr;
    arrBinCount[iBin] := arrBinCount[iBin] + 1;
END_IF

// ---- 输出：按目标归一化位置查表，施加修正 ----
IF rHalfRange > 0.001 THEN
    rNorm := (rTargetRaw - rMidpoint + rHalfRange) / (2.0 * rHalfRange);
ELSE
    rNorm := 0.5;
END_IF
IF rNorm < 0.0 THEN rNorm := 0.0; END_IF
IF rNorm > 1.0 THEN rNorm := 1.0; END_IF

iBin := REAL_TO_INT(rNorm * INT_TO_REAL(NUM_BINS - 1));
IF iBin < 0 THEN iBin := 0; END_IF
IF iBin > NUM_BINS - 1 THEN iBin := NUM_BINS - 1; END_IF

rVirtualTarget := rMidpoint + (rTargetRaw - rMidpoint) * arrScale[iBin];
rOutput := rVirtualTarget - rTargetRaw;

bNewCyclePrev := bNewCycle;

CASE Mode OF 
	//默认
	 1: //一阶惯性
	   //G(s) = K / (T*s + 1)
       // G(s) 差分方程 = (K*Ts*z + K*Ts)/((2*T + Ts)*z + Ts - 2*T)
	   y := (K*Ts*u + K*Ts*u_1-y_1*(Ts-2*T))/(2*T + Ts);
	   y_1:=y;
	   u_1:=u;
	 2://二阶方程
	  tn2 := T * T;
	  int1(X := u * K / tn2 - I1 * 0.5 * D / T - I2 / TN2, Y := I1);
	  int2(X := I1,Y := I2);
	  y := I2;	
END_CASE

// ============================================================
// 每周期首先执行数据打包（PLC→PC）
// 这是最先执行的步骤：将 PLC 当前所有需要上传的状态、数据
// 写入 INPUT_REGISTER 缓冲区，为后续 TCP_Write 发送做准备。
// 必须在 TCP_Write 之前调用，否则发送的是上一周期的旧数据。
// ============================================================
TCP_PLC_to_PC();
(*
// ============================================================
// 初始化：动态计算 FOR 循环上界
// mark_for_mun = SIZEOF(write_mark_bool) - 1
// 仅在首次执行时计算一次，后续周期不再重复计算（因为数组大小固定）
// ============================================================
IF initial_run THEN
    mark_for_mun := SIZEOF(write_mark_bool) - 1;
END_IF

// ============================================================
// 服务器异常后 FT 自动重启使能
// 容错重启机制：
//   当 TCP_Server_open 出现错误（xError=TRUE）或句柄丢失（hServer=0）时，
//   blink_server 开始闪烁 server_en（反复 FALSE/TRUE），产生上升沿触发重新打开服务器。
//   当服务器恢复正常（xError=FALSE 且 hServer≠0）时，server_en 保持 TRUE，闪烁停止。
// ============================================================
IF TCP_Server_open.xError OR (TCP_Server_open.hServer = 0) THEN
    blink_server(i_enable := TRUE, out_bool => server_en);
ELSE
    server_en := TRUE;
    blink_server(i_enable := FALSE);
END_IF

// ============================================================
// 启动/重启 TCP Server
// 服务器生命周期第一步：open（打开套接字）
//   - xEnable 上升沿触发：绑定 IP_ADR_server + ServerPORT，开始监听
//   - 输出 xBusy=TRUE 表示正在监听，hServer 为服务器句柄（供 TCP_Connection 使用）
//   - 输出 xDone=TRUE 表示服务器已关闭（xEnable 下降沿时）
//   - 输出 xError=TRUE 表示打开失败
// 当 connectNG（连接丢失）或首次运行时，重新调用以确保服务器处于监听状态
// ============================================================
IF connectNG OR initial_run THEN
    cishuhaha := cishuhaha + 1;
    TCP_Server_open(
        xEnable  := server_en,
        ipAddr   := IP_ADR_server,
        uiPort   := ServerPORT,
        xDone    => ,
        xBusy    => ,
        xError   => ,
        eError   => ,
        hServer  => );
END_IF

// ============================================================
// 检测客户端连接
// 服务器生命周期第二步：accept（接受客户端连接）
//   - xEnable 持续为 TRUE 时，TCP_Connection 等待客户端连接
//   - hServer 由 TCP_Server_open 提供，标识在哪个服务器上等待连接
//   - 连接成功后 xActive=TRUE，hConnection 为连接句柄（供 Read/Write 使用）
//   - xError=TRUE 表示连接失败
//   re_connection 检测连接丢失的上升沿（connectNG 从 FALSE→TRUE），
//   短暂禁用 TCP_Connection 以触发重新等待连接
// ============================================================
connectNG := (TCP_Connection.hConnection = 0);
re_connection(CLK := connectNG);

TCP_Connection(
    xEnable     := TCP_Server_open.xBusy AND NOT re_connection.Q,
    hServer     := TCP_Server_open.hServer,
    xDone       => ,
    xBusy       => ,
    xError      => ,
    eError      => ,
    xActive     => ,
    hConnection => );

// ============================================================
// READ：接收上位机数据 → HOLDING_REGISTER
// 服务器生命周期第三步：read（读取数据）
//   - xEnable 持续为 TRUE 时，每周期尝试从已建立的连接中读取数据
//   - hConnection 由 TCP_Connection 提供
//   - szSize 指定读取长度 = HOLDING_REGISTER 的大小
//   - pData 指向 HOLDING_REGISTER 的地址，数据直接写入该缓冲区
//   - xReady=TRUE 表示有新数据到达（可在此触发解析）
//   - xDone=TRUE 表示读取完成
//   - 读取到的数据将由最后的 TCP_PC_to_PLC() 进行解析
// ============================================================
server_read(
    xEnable     := TCP_Connection.xActive,
    hConnection := TCP_Connection.hConnection,
    szSize      := SIZEOF(TCP_PC_to_PLC.HOLDING_REGISTER),
    pData       := ADR(TCP_PC_to_PLC.HOLDING_REGISTER),
    xDone       => ,
    xBusy       => ,
    xError      => ,
    eError      => ,
    xReady      => ,
    szCount     => );

// ============================================================
// WRITE：发送 INPUT_REGISTER → 上位机（每周期写一次，交替触发）
// 服务器生命周期第四步：write（写入数据）
//   使用 FOR 循环 + write_mark_bool 交替触发方案：
//   - i_for=0: write_mark_bool[0]=FALSE → xExecute=FALSE（下降沿，为下次上升沿做准备）
//   - i_for=1: write_mark_bool[1]=TRUE  → xExecute=TRUE（上升沿，触发本次发送）
//   每个扫描周期内，同一个 server_write 功能块被调用两次：
//     第一次(FALSE)复位内部状态，第二次(TRUE)产生上升沿触发发送。
//   这是因为 NBS.TCP_Write 的 xExecute 需要上升沿触发，
//   如果 xExecute 始终为 TRUE 则只会发送一次，不会持续发送。
//   交替触发确保每个 10ms 周期都能成功发送一帧数据。
//   发送的数据是 INPUT_REGISTER，由 TCP_PLC_to_PC() 在周期开始时打包完毕。
// ============================================================
FOR i_for := 0 TO mark_for_mun DO
    server_write(
        xExecute    := TCP_Connection.xActive AND write_mark_bool[i_for],
        udiTimeOut  := 3008,
        hConnection := TCP_Connection.hConnection,
        szSize      := SIZEOF(TCP_PLC_to_PC.INPUT_REGISTER),
        pData       := ADR(TCP_PLC_to_PC.INPUT_REGISTER),
        xDone       => write_done_bool[i_for],
        xBusy       => write_busy_bool[i_for],
        xError      => write_error_bool[i_for],
        eError      => );
END_FOR


// ============================================================
// 结束初始化标志
// ============================================================
IF initial_run THEN
    initial_run := FALSE;
END_IF

// ============================================================
// 解析上位机数据（PC→PLC）
// 这是最后执行的步骤：从 HOLDING_REGISTER 中提取上位机下发的
// 各项参数（如设定值、命令等），写入对应的 PLC 变量。
// 必须在 TCP_Read 之后调用，因为此时 HOLDING_REGISTER 中才有最新接收的数据。
// 执行顺序总结：打包(TCP_PLC_to_PC) → 发送(TCP_Write) → 接收(TCP_Read) → 解析(TCP_PC_to_PLC)
// ============================================================

*)
// ============================================================
// 10 ms 帧计数递增（PLC→PC 帧计数器）
// FrameTick 每周期 +1，写入 PP_FrameCounter_PLC，
// 上位机可通过此值判断 PLC 是否在正常运行和通讯
// ============================================================
FrameTick := FrameTick + 1;
GVL_PulsePressure.PP_FrameCounter_PLC := DINT_TO_REAL(FrameTick);

TCP_PC_to_PLC();

{*
25.01为水侧产品端压力

26.01为剂侧产品端低压力传感器，用于低压测试
27.01为剂侧产品端15MPa压力传感器，用于爆破实验
*}

//水侧产品端压力
PP_Water_ActualPressure := PRG_DeviceControl.toPC_Pressure_25_01;
Water_Pressure_Filter(in:= PP_Water_ActualPressure,t:= T#50MS);
GVL_PulsePressure.PP_Water_ActualPressure := Water_Pressure_Filter.out;
{*
   测试模式 0=水路脉冲 1=油路(剂侧)脉冲 2=水路爆破 3=油路(剂侧)爆破
*}

//剂侧产品端压力
IF PP_TestMode=1 THEN 
  PP_Oil_ActualPressure:=PRG_DeviceControl.toPC_Pressure_26_01; //低压
ELSIF PP_TestMode=3 THEN
   PP_Oil_ActualPressure:=PRG_DeviceControl.toPC_Pressure_27_01; //高压
END_IF
Oil_Pressure_Filter(in:= PP_Oil_ActualPressure,t:= T#100MS);
GVL_PulsePressure.PP_Oil_ActualPressure := Oil_Pressure_Filter.out;


//方向系数
PWMotion.FPGAData.Axis1.OutputCoefficient := 1;


// ============================================================
// 自定义波形上传处理 (任何状态下都执行)
// 上升沿检测：当Upload_Commit从0→1时触发加载
// 加载后状态回写：1=成功 2=点数非法
// ============================================================
IF GVL_PulsePressure.PP_WaveUpload_Commit = 1.0 AND NOT bCommitPrev THEN
    nPts := REAL_TO_INT(GVL_PulsePressure.PP_WaveUpload_NumPoints);
    iCh  := REAL_TO_INT(GVL_PulsePressure.PP_WaveUpload_Channel);

    IF nPts >= 2 AND nPts <= 2000 THEN
        IF iCh = 0 THEN
            // 水路
            fbWaveGen_W.LoadCustomWaveform(
                pData   := ADR(GVL_PulsePressure.PP_WaveUpload_Data),
                nPoints := nPts
            );
        ELSE
            // 油路
            fbWaveGen_O.LoadCustomWaveform(
                pData   := ADR(GVL_PulsePressure.PP_WaveUpload_Data),
                nPoints := nPts
            );
        END_IF
        GVL_PulsePressure.PP_WaveUpload_Status := 1.0;  // 已加载
    ELSE
        GVL_PulsePressure.PP_WaveUpload_Status := 2.0;  // 错误
    END_IF
END_IF
bCommitPrev := (GVL_PulsePressure.PP_WaveUpload_Commit = 1.0);


// ============================================================
// 循环计数清零（上升沿检测，任何状态下都执行）
// PC写入CycleReset=1.0触发清零，清零后PC应写回0.0
// ============================================================
IF GVL_PulsePressure.PP_Water_CycleReset = 1.0 AND NOT bWaterCycleResetPrev THEN
    GVL_PulsePressure.PP_Water_CyclesDone := 0.0;
    GVL_PulsePressure.PP_TotalCyclesDone := 0.0;
END_IF
bWaterCycleResetPrev := (GVL_PulsePressure.PP_Water_CycleReset = 1.0);

IF GVL_PulsePressure.PP_Oil_CycleReset = 1.0 AND NOT bOilCycleResetPrev THEN
    GVL_PulsePressure.PP_Oil_CyclesDone := 0.0;
    GVL_PulsePressure.PP_TotalCyclesDone := 0.0;
END_IF
bOilCycleResetPrev := (GVL_PulsePressure.PP_Oil_CycleReset = 1.0);

// ============================================================
// PC命令解析
// PP_SysCommand: 0=空闲 1=冲洗排气 2=运行 3=停止
// 命令变化时触发状态切换
// ============================================================
iCmd := REAL_TO_INT(GVL_PulsePressure.PP_SysCommand);
bCmdChanged := (iCmd <> iCmdPrev);
iCmdPrev := iCmd;

// 命令变化时执行状态切换
IF bCmdChanged THEN
    CASE iCmd OF
        0: // 回空闲
            iState := 0;
        1: // 冲洗排气
            InitializeControllers();
            rFlushDuration := GVL_PulsePressure.PP_FlushDuration;
            rFlushOutput := GVL_PulsePressure.PP_FlushValveOutput;
            IF rFlushOutput < 0.5 THEN rFlushOutput := 2.0; END_IF
            IF rFlushOutput > 5.0 THEN rFlushOutput := 5.0; END_IF
            rFlushTimer := 0.0;
            iState := 1;
        2: // 运行（自动序列：油缸检查→预加压→运行）
		    rFlushTimer := 0.0;
            InitializeControllers();
            iState := 2;  // 先进入预加压，内部自动推进到运行
        3: // 停止
            rStopRampVal_W := GVL_PulsePressure.PP_Water_ActualPressure;
            rStopRampVal_O := GVL_PulsePressure.PP_Oil_ActualPressure;
            iState := 4;
    END_CASE
    GVL_PulsePressure.PP_StateReady := 0.0;
END_IF

// ============================================================
// 通道选择（互斥：水路和油路不能同时激活）
// 互斥逻辑说明:
//   TestMode=0 → 水路脉冲 → bWaterActive=TRUE, bOilActive=FALSE
//   TestMode=1 → 油路脉冲 → bWaterActive=FALSE, bOilActive=TRUE
//   TestMode=2 → 水路爆破 → bWaterActive=TRUE, bOilActive=FALSE
//   TestMode=3 → 油路爆破 → bWaterActive=FALSE, bOilActive=TRUE
// 安全保护: 若参数异常导致两路同时激活，强制关闭油路仅保留水路
// 这样可避免两路同时输出控制量导致液压冲突
// ============================================================
bWaterActive := (GVL_PulsePressure.PP_TestMode = 0.0 OR GVL_PulsePressure.PP_TestMode = 2.0);
bOilActive   := (GVL_PulsePressure.PP_TestMode = 1.0 OR GVL_PulsePressure.PP_TestMode = 3.0);

//1.水侧测试：开启10.02、10.04，关闭10.01、10.03
IF bWaterActive=TRUE THEN
	PRG_DeviceControl.fromPC_TD_Valve_10_01 := FALSE;
	PRG_DeviceControl.fromPC_TD_Valve_10_02 := TRUE;
	PRG_DeviceControl.fromPC_TD_Valve_10_03 := FALSE;
	PRG_DeviceControl.fromPC_TD_Valve_10_04 := TRUE;
END_IF

//2.剂测测试：开启10.01、10.03，关闭10.02、10.04
IF bOilActive=TRUE THEN
	PRG_DeviceControl.fromPC_TD_Valve_10_01 := TRUE;
	PRG_DeviceControl.fromPC_TD_Valve_10_02 := FALSE;
	PRG_DeviceControl.fromPC_TD_Valve_10_03 := TRUE;
	PRG_DeviceControl.fromPC_TD_Valve_10_04 := FALSE;
END_IF

// 互斥保护：如果因参数异常导致两路同时激活，强制只保留水路
IF bWaterActive AND bOilActive THEN
    bOilActive := FALSE;
END_IF



// ============================================================
// 计算系统参数
// 供油压力的单位换算: MPa → Pa，并设置安全下限
// 总容积 = 基础容积 + 被试件容积，并设置安全下限
// ============================================================
rPs_Pa := GVL_PulsePressure.PP_Hydro_WorkingPressure * 1.0E6;
IF rPs_Pa < 1.0E6 THEN rPs_Pa := 35.0E6; END_IF  // 默认35MPa

rVTotal_W := GVL_PulsePressure.PP_Water_VBase + GVL_PulsePressure.PP_Water_VSpecimen;
rVTotal_O := GVL_PulsePressure.PP_Oil_VBase + GVL_PulsePressure.PP_Oil_VSpecimen;
IF rVTotal_W < 1.0E-6 THEN rVTotal_W := 0.7E-3; END_IF  // 默认0.7L
IF rVTotal_O < 1.0E-6 THEN rVTotal_O := 0.7E-3; END_IF

// ============================================================
// 计算实际PMin（直接使用上位机设定值，0即为0MPa）
// ============================================================
rActualPMin_W := GVL_PulsePressure.PP_Water_MinPressure;
IF rActualPMin_W < 0.0 THEN rActualPMin_W := 0.0; END_IF
IF rActualPMin_W >= GVL_PulsePressure.PP_Water_TargetPressure THEN
    rActualPMin_W := GVL_PulsePressure.PP_Water_TargetPressure * 0.9;
END_IF

rActualPMin_O := GVL_PulsePressure.PP_Oil_MinPressure;
IF rActualPMin_O < 0.0 THEN rActualPMin_O := 0.0; END_IF
IF rActualPMin_O >= GVL_PulsePressure.PP_Oil_TargetPressure THEN
    rActualPMin_O := GVL_PulsePressure.PP_Oil_TargetPressure * 0.9;
END_IF

// 获取当前激活通道的油缸位置
IF bWaterActive THEN
   rCylinderPos := PRG_HydraulicUnit_Control.Water_CylinderPos;
ELSIF bOilActive THEN
   rCylinderPos := PRG_HydraulicUnit_Control.Oil_CylinderPos;
END_IF

// ============================================================
// 状态机
// ============================================================
CASE iState OF

// ------------------------------------------------------------
// 状态0: 空闲
// 所有控制输出清零，等待PC写入新命令
// ------------------------------------------------------------
0:
    bRunning := FALSE;
    rUTotal_W := 0.0;
    rUTotal_O := 0.0;
    GVL_PulsePressure.PP_SysState := 0.0;  // 空闲
    GVL_PulsePressure.PP_FlushTimeRemaining := 0.0;
    GVL_PulsePressure.PP_StateReady := 0.0;

// ------------------------------------------------------------
// 状态1: 冲洗排气 — 低压循环排出管路中的空气
// PLC置StateReady=1通知PC冲洗完成，由PC决定何时发下一命令。
// ------------------------------------------------------------
1:
    bRunning := TRUE;
    GVL_PulsePressure.PP_SysState := 1.0;  // 冲洗排气

    // 冲洗计时
    rFlushTimer := rFlushTimer + rDt;
    GVL_PulsePressure.PP_FlushTimeRemaining := rFlushDuration - rFlushTimer;
    IF GVL_PulsePressure.PP_FlushTimeRemaining < 0.0 THEN
        GVL_PulsePressure.PP_FlushTimeRemaining := 0.0;
    END_IF

    // 隔离缸往复运动（10秒切换方向）
	(*
    IF rFlushToggleTimer >= 10.0  THEN
        rFlushToggleTimer := 0.0;
        bFlushDirection := NOT bFlushDirection;
    END_IF
    *)
    IF  rCylinderPos >= 95.0 AND NOT bFlushDirection THEN
        bFlushDirection := NOT bFlushDirection;
    END_IF

    IF  rCylinderPos <= 5.0 AND  bFlushDirection THEN
        bFlushDirection := NOT bFlushDirection;
    END_IF

    IF NOT bFlushDirection THEN
        PWMOTION.FPGAData.Axis1.Output_ManualSet := 5;   // 正向
    ELSE
        PWMOTION.FPGAData.Axis1.Output_ManualSet := -5;  // 反向
    END_IF

    // 冲洗时间到 → 置就绪标志，通知PC
	(*
    IF rFlushTimer >= rFlushDuration THEN
        GVL_PulsePressure.PP_FlushTimeRemaining := 0.0;
        GVL_PulsePressure.PP_StateReady := 1.0;
    END_IF
*)
// ------------------------------------------------------------
// 状态2: 预加压 — 自动序列：检查油缸到位→预加压→自动进入运行
// 油缸到位条件：位移 < 2.0mm
// 预加压到位条件：误差 < 0.2MPa，到位后自动推进到状态3(运行)
// ------------------------------------------------------------
2:
    bRunning := TRUE;
    GVL_PulsePressure.PP_SysState := 2.0;  // 预加压

    rFlushTimer := rFlushTimer + rDt;
    // 检查油缸是否到位（< 2.0mm）
    IF rCylinderPos > 30.0 THEN
        // 油缸未到位，等待，不输出压力控制
        PWMOTION.FPGAData.Axis1.Output_ManualSet := -5;
    ELSE
        // 油缸到位，执行预加压
        // 水路预加压
        IF bWaterActive THEN
            rPrePressTarget_W := rActualPMin_W;
            rPrePressErr_W := rPrePressTarget_W - GVL_PulsePressure.PP_Water_ActualPressure;
            rUTotal_W := rPrePressKp * rPrePressErr_W;
            IF rUTotal_W > 10.0 THEN rUTotal_W := 10.0; END_IF
            IF rUTotal_W < -10.0 THEN rUTotal_W := -10.0; END_IF

            IF rUTotal_W > 0 THEN
                PWMOTION.FPGAData.Axis1.Output_ManualSet := rUTotal_W*10 ;
            END_IF
            IF rUTotal_W < 0 THEN
                PWMOTION.FPGAData.Axis1.Output_ManualSet := rUTotal_W*10 ;
            END_IF

            // 预加压到位 → 自动进入运行
            IF ABS(rPrePressErr_W) < 0.2 THEN
                iState := 3;
            END_IF
        ELSE
            rUTotal_W := 0.0;
        END_IF

        // 油路预加压
        IF bOilActive THEN
            rPrePressTarget_O := rActualPMin_O;
            rPrePressErr_O := rPrePressTarget_O - GVL_PulsePressure.PP_Oil_ActualPressure;
            rUTotal_O := rPrePressKp * rPrePressErr_O;
            IF rUTotal_O > 10.0 THEN rUTotal_O := 10.0; END_IF
            IF rUTotal_O < -10.0 THEN rUTotal_O := -10.0; END_IF

            IF rUTotal_O > 0 THEN
                PWMOTION.FPGAData.Axis1.Output_ManualSet := rUTotal_O*10;
            END_IF
            IF rUTotal_O < 0 THEN
                PWMOTION.FPGAData.Axis1.Output_ManualSet := rUTotal_O*10;
            END_IF

            // 预加压到位 → 自动进入运行
            IF ABS(rPrePressErr_O) < 0.2 THEN
                iState := 3;
            END_IF
        ELSE
            rUTotal_O := 0.0;
        END_IF
    END_IF

// ------------------------------------------------------------
// 状态3: 运行 — MFF + ILC + ADRC 复合控制
// 此状态下执行完整的6步控制流水线:
//   1) 波形生成 → 2) 计算跟踪误差 → 3) MFF前馈
//   → 4) ILC前馈 → 5) ADRC反馈 → 6) 三路叠加
// ============================================================
3:
    bRunning := TRUE;
    GVL_PulsePressure.PP_SysState := 3.0;  // 运行

    // ==================== 水路控制 ====================
    IF bWaterActive THEN
        RunWaterChannel();
    ELSE
        rUTotal_W := 0.0;
    END_IF

    // ==================== 油路控制 ====================
    IF bOilActive THEN
        RunOilChannel();
    ELSE
        rUTotal_O := 0.0;
    END_IF

    // 检查目标循环数（到达后自动停止）
    IF bWaterActive AND GVL_PulsePressure.PP_Water_TargetCycles > 0.0 THEN
        IF GVL_PulsePressure.PP_Water_CyclesDone >= GVL_PulsePressure.PP_Water_TargetCycles THEN
            rStopRampVal_W := GVL_PulsePressure.PP_Water_ActualPressure;
            rStopRampVal_O := GVL_PulsePressure.PP_Oil_ActualPressure;
            iState := 4;
        END_IF
    END_IF
    IF bOilActive AND GVL_PulsePressure.PP_Oil_TargetCycles > 0.0 THEN
        IF GVL_PulsePressure.PP_Oil_CyclesDone >= GVL_PulsePressure.PP_Oil_TargetCycles THEN
            rStopRampVal_W := GVL_PulsePressure.PP_Water_ActualPressure;
            rStopRampVal_O := GVL_PulsePressure.PP_Oil_ActualPressure;
            iState := 4;
        END_IF
    END_IF

// ------------------------------------------------------------
// 状态4: 停止中 — 缓慢卸压
// 停止斜坡机制说明:
//   进入状态4时，rStopRampVal已在InitializeControllers中被初始化为当前实际压力值。
//   每个控制周期(1ms)按 rStopRampRate=5MPa/s 递减目标值，
//   并用与预加压相同的比例控制(Kp=2.0)跟踪递减目标值。
//   这实现了从当前压力到零的平滑下降，避免直接关闭阀门导致的
//   水锤效应或压力冲击。当实际压力降到0.5MPa以下时认为卸压完成，
//   返回空闲状态(状态0)。
// ------------------------------------------------------------
4:
    GVL_PulsePressure.PP_SysState := 4.0;  // 停止中

    // 水路卸压（仅对激活通道执行）
    IF bWaterActive THEN
        IF GVL_PulsePressure.PP_Water_ActualPressure > 0.5 THEN
            // 斜坡目标值每ms递减 rStopRampRate*0.001 = 0.005MPa
            // 即5MPa/s的卸压速率
            rStopRampVal_W := rStopRampVal_W - rStopRampRate * rDt;
            IF rStopRampVal_W < 0.0 THEN rStopRampVal_W := 0.0; END_IF
            rPrePressErr_W := rStopRampVal_W - GVL_PulsePressure.PP_Water_ActualPressure;
            PWMOTION.FPGAData.Axis1.Output_ManualSet := rUTotal_W := rPrePressKp * rPrePressErr_W;
        ELSE
            PWMOTION.FPGAData.Axis1.Output_ManualSet := rUTotal_W := 0.0;
        END_IF
    END_IF

    // 油路卸压（仅对激活通道执行）
    IF bOilActive THEN
        IF GVL_PulsePressure.PP_Oil_ActualPressure > 0.5 THEN
            // 与水路相同的斜坡卸压机制
            rStopRampVal_O := rStopRampVal_O - rStopRampRate * rDt;
            IF rStopRampVal_O < 0.0 THEN rStopRampVal_O := 0.0; END_IF
            rPrePressErr_O := rStopRampVal_O - GVL_PulsePressure.PP_Oil_ActualPressure;
            PWMOTION.FPGAData.Axis1.Output_ManualSet:= rUTotal_O := rPrePressKp * rPrePressErr_O;
        ELSE
            PWMOTION.FPGAData.Axis1.Output_ManualSet := rUTotal_O := 0.0;
        END_IF
    END_IF

    // 激活通道卸压完成 → 置就绪标志，通知PC（PC发命令0回空闲）
    IF bWaterActive AND GVL_PulsePressure.PP_Water_ActualPressure < 0.5 THEN
        GVL_PulsePressure.PP_StateReady := 1.0;
    ELSIF bOilActive AND GVL_PulsePressure.PP_Oil_ActualPressure < 0.5 THEN
        GVL_PulsePressure.PP_StateReady := 1.0;
    END_IF

// ------------------------------------------------------------
// 状态5: 故障
// 由高压保护触发，所有输出强制清零
// PC发命令0即可恢复到空闲状态
// ------------------------------------------------------------
5:
    rUTotal_W := 0.0;
    rUTotal_O := 0.0;
    PWMOTION.FPGAData.Axis1.Output_ManualSet := 0;
    GVL_PulsePressure.PP_SysState := 5.0;  // 故障

END_CASE

// ============================================================
// 高压保护 — 任何状态下都执行，优先级高于状态机
// 说明: 当实际压力超过设定的限值(HighLimit)时，
//   1) 强制控制输出为-5V(最大回油方向)，打开回油阀快速泄压
//   2) 立即将状态机切换到故障状态(状态5)
//   此保护在CASE语句之后执行，因此会覆盖任何状态下的控制输出，
//   确保即使运行状态中出现超压也能立即响应。
//   高压保护条件: HighLimit > 0 且 实际压力 > HighLimit
//   HighLimit > 0的检查是为了防止未设定限值时误触发
// ============================================================
IF bWaterActive AND GVL_PulsePressure.PP_Water_ActualPressure > GVL_PulsePressure.PP_Water_HighLimit
   AND GVL_PulsePressure.PP_Water_HighLimit > 0.0 THEN
    PWMOTION.FPGAData.Axis1.Output_ManualSet := rUTotal_W := 0.0;  // 强制回油
	PRG_DeviceControl.fromPC_Pne_Valve_YV1 := TRUE;
    iState := 5;
ELSE
    PRG_DeviceControl.fromPC_Pne_Valve_YV1 := FALSE;
END_IF

IF bOilActive AND GVL_PulsePressure.PP_Oil_ActualPressure > GVL_PulsePressure.PP_Oil_HighLimit
   AND GVL_PulsePressure.PP_Oil_HighLimit > 0.0 THEN
    PWMOTION.FPGAData.Axis1.Output_ManualSet := rUTotal_O := 0.0;
	PRG_DeviceControl.fromPC_Pne_Valve_YV7 := TRUE;
    iState := 5;
ELSE
	PRG_DeviceControl.fromPC_Pne_Valve_YV7 := FALSE;
END_IF

// ============================================================
// 急停保护 — 任何状态下都执行
// 急停时强制切到停止状态(状态4)进行斜坡卸压
// ============================================================
IF GVL_PulsePressure.PP_EmergencyStop = 1.0 AND iState <> 0 AND iState <> 4 AND iState <> 5 THEN
    rStopRampVal_W := GVL_PulsePressure.PP_Water_ActualPressure;
    rStopRampVal_O := GVL_PulsePressure.PP_Oil_ActualPressure;
    iState := 4;
END_IF

// ============================================================
// 输出到全局变量
// ============================================================
// 总控制输出限幅: ±10V 对应伺服阀最大驱动范围
IF rUTotal_W > 10.0 THEN rUTotal_W := 10.0; END_IF
IF rUTotal_W < -10.0 THEN rUTotal_W := -10.0; END_IF
IF rUTotal_O > 10.0 THEN rUTotal_O := 10.0; END_IF
IF rUTotal_O < -10.0 THEN rUTotal_O := -10.0; END_IF

GVL_PulsePressure.PP_Water_ControlOutput := rUTotal_W;
GVL_PulsePressure.PP_Oil_ControlOutput := rUTotal_O;

// 各功能块复位说明:
// fbWaveGen(bReset:=TRUE)  — 清零波形发生器内部相位、周期计数器，
//                            确保第一脉冲从正确相位开始
// fbMFF(bEnable:=FALSE)    — 禁用模型前馈并清零内部状态，
//                            避免旧的前馈数据影响新测试
// fbADRC(bReset:=TRUE)     — 复位自抗扰控制器，清零ESO状态变量z1/z2，
//                            使ADRC从零误差开始调整
// fbILC(bReset:=TRUE)      — 清零迭代学习存储的历史误差数据，
//                            确保新一轮测试从第一个周期重新开始学习

// 重置所有功能块
fbWaveGen_W(bReset := TRUE);
fbMFF_W(bEnable := FALSE);
fbADRC_W(bReset := TRUE);
fbILC_W(bReset := TRUE);

fbWaveGen_O(bReset := TRUE);
fbMFF_O(bEnable := FALSE);
fbADRC_O(bReset := TRUE);
fbILC_O(bReset := TRUE);

// 重置峰值检测器
// 将峰值压力归零，避免上一轮测试的峰值数据残留
rPeakPressure_W := 0.0;
rPeakPressure_O := 0.0;


    // 初始化卸压斜坡值
    // 将停止斜坡目标值设为当前实际压力，作为卸压起始点
    // 这样进入状态3时斜坡会从当前压力开始以5MPa/s速率递减
    rStopRampVal_W := GVL_PulsePressure.PP_Water_ActualPressure;
    rStopRampVal_O := GVL_PulsePressure.PP_Oil_ActualPressure;

// 读取系统参数 (带默认值保护)
rBetaE := GVL_PulsePressure.PP_Sys_BetaE;
IF rBetaE < 1.0E6 THEN rBetaE := 1.5E7; END_IF

rCLeak := GVL_PulsePressure.PP_Sys_CLeak;
IF rCLeak < 0.0 THEN rCLeak := 1.0E-12; END_IF

// ---- 1. 波形生成 ----
// 根据TestMode指定的波形类型(正弦/方波/三角/梯形/自定义)
// 和压力范围(PMin~PMax)生成实时目标压力
// PMin = rActualPMin（由上位机MinPressure参数决定）
// PMax = TargetPressure
fbWaveGen_W(
    bEnable       := TRUE,
    rPMin         := rActualPMin_W,
    rPMax         := GVL_PulsePressure.PP_Water_TargetPressure,
    rFrequency    := GVL_PulsePressure.PP_Water_Frequency,
    iWaveType     := REAL_TO_INT(GVL_PulsePressure.PP_Water_WaveType),
    rDutyCycle    := GVL_PulsePressure.PP_Water_DutyCycle / 100.0,
    rRisePct      := GVL_PulsePressure.PP_Water_RisePct,
    rHoldPct      := GVL_PulsePressure.PP_Water_HoldPct,
    rFallPct      := GVL_PulsePressure.PP_Water_FallPct,
    rDt           := rDt,
    bReset        := FALSE,
	nMffLeadSteps := 120
);

// 更新GVL反馈
(*
IF fbWaveGen_W.rTarget >= 0.15 THEN
   GVL_PulsePressure.PP_Water_SetpointPressure := 0.15 + (fbWaveGen_W.rTarget-0.15)*0.5  ;
END_IF

IF fbWaveGen_W.rTarget < 0.15 THEN
   GVL_PulsePressure.PP_Water_SetpointPressure := 0.15 + (fbWaveGen_W.rTarget-0.15)*1.45  ;
END_IF
*)

GVL_PulsePressure.PP_Water_SetpointPressure := fbWaveGen_W.rTarget;
GVL_PulsePressure.PP_Water_WavePhase := fbWaveGen_W.rPhase * 360.0;
GVL_PulsePressure.PP_Water_Frequency_FB := GVL_PulsePressure.PP_Water_Frequency;

// 周期计数
IF fbWaveGen_W.bNewCycle THEN
    GVL_PulsePressure.PP_Water_CyclesDone := GVL_PulsePressure.PP_Water_CyclesDone + 1.0;
    GVL_PulsePressure.PP_TotalCyclesDone := GVL_PulsePressure.PP_TotalCyclesDone + 1.0;
    // 更新峰值：每个脉冲周期结束时，将本周期内检测到的峰值压力锁存到GVL
    GVL_PulsePressure.PP_Water_PeakPressure := rPeakPressure_W;
    rPeakPressure_W := 0.0;
END_IF

// 峰值检测
IF GVL_PulsePressure.PP_Water_ActualPressure > rPeakPressure_W THEN
    rPeakPressure_W := GVL_PulsePressure.PP_Water_ActualPressure;
END_IF

// ---- 2. 计算跟踪误差 ----
// e = 目标压力 - 实际压力, 正值表示压力不足需增加
rError_W := fbWaveGen_W.rTarget - GVL_PulsePressure.PP_Water_ActualPressure;
GVL_PulsePressure.PP_Water_PressureError := rError_W;

// ---- 3. 模型前馈 ----
// MFF基于液压系统逆模型计算前馈控制量
// 输入: 目标压力、前一周期目标压力、系统物理参数
// 输出: u_mff — 约占所需总控制量的90%
fbMFF_W(
    bEnable        := TRUE,
    rTargetMPa     := fbWaveGen_W.rTargetLead,
    rTargetPrevMPa := fbWaveGen_W.rTargetLeadPrev,
    rDt            := rDt,
    rBetaE         := rBetaE,
    rVTotal        := rVTotal_W,
    rPs            := rPs_Pa,
    rCLeak         := rCLeak,
    rValveQnom     := GVL_PulsePressure.PP_Water_ValveQnom,
    rValveDPnom    := GVL_PulsePressure.PP_Water_ValveDPnom,
    rValveUmax     := GVL_PulsePressure.PP_Water_ValveUmax,
    iValveDynMode  := REAL_TO_INT(GVL_PulsePressure.PP_Water_ValveDynMode),
    rValveDynParam := GVL_PulsePressure.PP_Water_ValveDynParam
);
rUMff_W := fbMFF_W.rOutput;
GVL_PulsePressure.PP_Water_MFF_Output := rUMff_W;

// 回写诊断: 反推得到的Kv和τv
GVL_PulsePressure.PP_Water_Kv := fbMFF_W.rKv_Calc;
GVL_PulsePressure.PP_Water_TauValve := fbMFF_W.rTauValve_Calc;

// ---- 4. ILC前馈 ----
// ILC利用上一周期同相位点的误差修正本周期控制量
// 每完成一个脉冲周期(bNewCycle)时更新学习存储
// 使能: 仅当PP_Water_ILC_Enable=1时参与控制


////四象限Alpha补偿算法+启动暖机
fbILC_W(
    bEnable         := (GVL_PulsePressure.PP_Water_ILC_Enable = 1.0),  // ILC总使能，上位机寄存器控制
    rTargetRaw      := fbWaveGen_W.rTarget,                             // 原始目标压力 (MPa)，来自波形发生器
    rActual         := GVL_PulsePressure.PP_Water_ActualPressure,       // 当前反馈压力 (MPa)
    iPointIndex     := fbWaveGen_W.iPointIndex,                         // 当前周期内采样点序号 (0~iPointsPerCycle-1)
    iPointsPerCycle := fbWaveGen_W.iPointsPerCycle,                     // 每周期总采样点数
    bNewCycle       := fbWaveGen_W.bNewCycle,                           // 新周期脉冲信号（上升沿触发学习更新）
    bReset          := FALSE,                                            // 复位：清零所有学习数据，恢复初始状态
    iMaxIterations  := REAL_TO_INT(GVL_PulsePressure.PP_Water_ILC_MaxIter), // 最大迭代次数，到达后锁定不再更新（0=不限制）
    rLearningRate   := GVL_PulsePressure.PP_Water_ILC_LearningRate,     // 幅值 scale 学习率，建议 0.2~0.4
    rAlphaLR        := 0.4,                                              // 波形形状（4象限α）学习率，建议 0.3~0.5
    bAlphaEnable    := TRUE,                                             // α形状学习使能，FALSE时只学幅值不改波形形状
    nWarmupCycles   := 3                                                 // 暖机周期数，前N周期透传不修正，防初始超压
);
//变形态
(*
fbILC_W(
    bEnable         := (GVL_PulsePressure.PP_Water_ILC_Enable = 1.0),
    rTargetRaw      := fbWaveGen_W.rTarget,
    rActual         := GVL_PulsePressure.PP_Water_ActualPressure,
    iPointIndex     := fbWaveGen_W.iPointIndex,
    iPointsPerCycle := fbWaveGen_W.iPointsPerCycle,
    bNewCycle       := fbWaveGen_W.bNewCycle,
    bReset          := FALSE,
    iMaxIterations  := REAL_TO_INT(GVL_PulsePressure.PP_Water_ILC_MaxIter),
    rLearningRate   := GVL_PulsePressure.PP_Water_ILC_LearningRate,
    rAlphaTarget    := 0.5,
    rAlphaLR        := 0.4
);
*)
(*

fbILC_W(
    bEnable         := (GVL_PulsePressure.PP_Water_ILC_Enable = 1.0),
    rTargetRaw      := fbWaveGen_W.rTarget,
    rActual         := GVL_PulsePressure.PP_Water_ActualPressure,
    iPointIndex     := fbWaveGen_W.iPointIndex,
    iPointsPerCycle := fbWaveGen_W.iPointsPerCycle,
    bNewCycle       := fbWaveGen_W.bNewCycle,
    bReset          := FALSE,
    iMaxIterations  := REAL_TO_INT(GVL_PulsePressure.PP_Water_ILC_MaxIter),
    rLearningRate   := GVL_PulsePressure.PP_Water_ILC_LearningRate
);
*)
rUIlc_W := fbILC_W.rOutput;
GVL_PulsePressure.PP_Water_ILC_Output := rUIlc_W;
GVL_PulsePressure.PP_Water_ILC_Iteration := INT_TO_REAL(fbILC_W.iIteration);


// 更新GVL反馈
(*
IF fbWaveGen_W.rTarget >= 0.15 THEN
   GVL_PulsePressure.PP_Water_SetpointPressure := 0.15 + (fbWaveGen_W.rTarget-0.15)*0.5  ;
END_IF

IF fbWaveGen_W.rTarget < 0.15 THEN
   GVL_PulsePressure.PP_Water_SetpointPressure := 0.15 + (fbWaveGen_W.rTarget-0.15)*1.45  ;
END_IF
*)

// 修正后的目标 = 原始目标 + ILC修正量
rTargetCorrected_W := fbILC_W.rVirtualTarget;
//GVL_PulsePressure.PP_Water_SetpointPressure := rTargetCorrected_W;

// ---- 2. 计算跟踪误差 ----
// e = 修正后目标 - 实际压力
rError_W := rTargetCorrected_W - GVL_PulsePressure.PP_Water_ActualPressure;
//rError_W := GVL_PulsePressure.PP_Water_SetpointPressure - GVL_PulsePressure.PP_Water_ActualPressure;
GVL_PulsePressure.PP_Water_PressureError := rError_W;

// ---- 5. ADRC反馈 ----
// ADRC(自抗扰控制)利用ESO扩张状态观测器实时估计系统总扰动
// rZ2为ESO输出的扰动估计(单位: MPa/s)，用于前馈补偿
// 与MFF+ILC叠加后可实时抑制非重复性扰动(如泄漏变化、负载波动)
fbADRC_W(
    bEnable   := TRUE,
    rError    := rError_W,
    rDt       := rDt,
    rVTotal   := rVTotal_W,
    bReset    := FALSE,
    rBetaE    := rBetaE,
    rPs       := rPs_Pa,
    rValveQnom  := GVL_PulsePressure.PP_Water_ValveQnom,
    rValveDPnom := GVL_PulsePressure.PP_Water_ValveDPnom,
    rValveUmax  := GVL_PulsePressure.PP_Water_ValveUmax,
	rPID_Kp := 4,
	rPID_Ki := 0,
	nCtrlMode :=1,
);
rUAdrc_W := fbADRC_W.rOutput;

// ADRC 诊断输出
GVL_PulsePressure.PP_Water_ADRC_Output := rUAdrc_W;
GVL_PulsePressure.PP_Water_ESO_Disturbance := fbADRC_W.rZ2;

// ---- 6. 三环复合: u = u_mff + u_ilc + u_adrc ----
// 总控制量为三路叠加:
//   u_mff:  模型前馈，提供基准控制量(约90%)
//   u_ilc:  迭代学习，修正重复性误差(约5-8%)
//   u_adrc: 自抗扰控制，补偿非重复性扰动(约2-5%)
//rUTotal_W := rUMff_W + rUIlc_W + rUAdrc_W;
//rUTotal_W :=   GVL_PulsePressure.PP_Water_SetpointPressure - 0.11  + rUAdrc_W;
rUTotal_W :=    rUAdrc_W;
//rUTotal_W :=  rUAdrc_W;
IF rUTotal_W > 10.0 THEN rUTotal_W := 10.0; END_IF
IF rUTotal_W < -10.0 THEN rUTotal_W := -10.0; END_IF

IF rUTotal_W > 0 THEN
	PWMOTION.FPGAData.Axis1.Output_ManualSet := rUTotal_W*10 ;
END_IF
IF rUTotal_W < 0 THEN
	PWMOTION.FPGAData.Axis1.Output_ManualSet := rUTotal_W*10    ;
END_IF

rBetaE := GVL_PulsePressure.PP_Sys_BetaE;
IF rBetaE < 1.0E6 THEN rBetaE := 1.4E9; END_IF

rCLeak := GVL_PulsePressure.PP_Sys_CLeak;
IF rCLeak < 0.0 THEN rCLeak := 1.0E-12; END_IF

// ---- 1. 波形生成 ----
fbWaveGen_O(
    bEnable       := TRUE,
    rPMin         := rActualPMin_O,
    rPMax         := GVL_PulsePressure.PP_Oil_TargetPressure,
    rFrequency    := GVL_PulsePressure.PP_Oil_Frequency,
    iWaveType     := REAL_TO_INT(GVL_PulsePressure.PP_Oil_WaveType),
    rDutyCycle    := GVL_PulsePressure.PP_Oil_DutyCycle / 100.0,
    rRisePct      := GVL_PulsePressure.PP_Oil_RisePct,
    rHoldPct      := GVL_PulsePressure.PP_Oil_HoldPct,
    rFallPct      := GVL_PulsePressure.PP_Oil_FallPct,
    rDt           := rDt,
    bReset        := FALSE
);
IF fbWaveGen_O.rTarget >= 1.5 THEN
   GVL_PulsePressure.PP_Oil_SetpointPressure := 1.5 + (fbWaveGen_O.rTarget-1.5)*0.7  ;
END_IF

IF fbWaveGen_O.rTarget < 1.5 THEN
   GVL_PulsePressure.PP_Oil_SetpointPressure := 1.5 + (fbWaveGen_O.rTarget-1.5)*1.4  ;
END_IF

GVL_PulsePressure.PP_Oil_WavePhase := fbWaveGen_O.rPhase * 360.0;
GVL_PulsePressure.PP_Oil_Frequency_FB := GVL_PulsePressure.PP_Oil_Frequency;

IF fbWaveGen_O.bNewCycle THEN
    GVL_PulsePressure.PP_Oil_CyclesDone := GVL_PulsePressure.PP_Oil_CyclesDone + 1.0;
    GVL_PulsePressure.PP_TotalCyclesDone := GVL_PulsePressure.PP_TotalCyclesDone + 1.0;
    GVL_PulsePressure.PP_Oil_PeakPressure := rPeakPressure_O;
    rPeakPressure_O := 0.0;
END_IF

IF GVL_PulsePressure.PP_Oil_ActualPressure > rPeakPressure_O THEN
    rPeakPressure_O := GVL_PulsePressure.PP_Oil_ActualPressure;
END_IF

// ---- 2. 跟踪误差 ----
rError_O := fbWaveGen_O.rTarget - GVL_PulsePressure.PP_Oil_ActualPressure;
GVL_PulsePressure.PP_Oil_PressureError := rError_O;

// ---- 3. 模型前馈 ----
fbMFF_O(
    bEnable        := TRUE,
    rTargetMPa     := fbWaveGen_O.rTarget,
    rTargetPrevMPa := fbWaveGen_O.rTargetPrev,
    rDt            := rDt,
    rBetaE         := rBetaE,
    rVTotal        := rVTotal_O,
    rPs            := rPs_Pa,
    rCLeak         := rCLeak,
    rValveQnom     := GVL_PulsePressure.PP_Oil_ValveQnom,
    rValveDPnom    := GVL_PulsePressure.PP_Oil_ValveDPnom,
    rValveUmax     := GVL_PulsePressure.PP_Oil_ValveUmax,
    iValveDynMode  := REAL_TO_INT(GVL_PulsePressure.PP_Oil_ValveDynMode),
    rValveDynParam := GVL_PulsePressure.PP_Oil_ValveDynParam
);
rUMff_O := fbMFF_O.rOutput;
GVL_PulsePressure.PP_Oil_MFF_Output := rUMff_O;

// 回写诊断: 反推得到的Kv和τv
GVL_PulsePressure.PP_Oil_Kv := fbMFF_O.rKv_Calc;
GVL_PulsePressure.PP_Oil_TauValve := fbMFF_O.rTauValve_Calc;

// ---- 4. ILC前馈 ----

rUIlc_O := fbILC_O.rOutput;
GVL_PulsePressure.PP_Oil_ILC_Output := rUIlc_O;
GVL_PulsePressure.PP_Oil_ILC_Iteration := INT_TO_REAL(fbILC_O.iIteration);

// ---- 5. ADRC反馈 ----
fbADRC_O(
    bEnable   := TRUE,
    rError    := rError_O,
    rDt       := rDt,
    rVTotal   := rVTotal_O,
    bReset    := FALSE,
    rBetaE    := rBetaE,
    rPs       := rPs_Pa,
    rValveQnom  := GVL_PulsePressure.PP_Oil_ValveQnom,
    rValveDPnom := GVL_PulsePressure.PP_Oil_ValveDPnom,
    rValveUmax  := GVL_PulsePressure.PP_Oil_ValveUmax,
	rPID_Kp := 0.4,
	rPID_Ki := 0 ,
	nCtrlMode :=1,
);
rUAdrc_O := fbADRC_O.rOutput;

// ADRC 诊断输出
GVL_PulsePressure.PP_Oil_ADRC_Output := rUAdrc_O;
GVL_PulsePressure.PP_Oil_ESO_Disturbance := fbADRC_O.rZ2;

// ---- 6. 三环复合 ----
//rUTotal_O := rUMff_O + rUIlc_O + rUAdrc_O;
rUTotal_O :=   rUAdrc_O;
IF rUTotal_O > 10.0 THEN rUTotal_O := 10.0; END_IF
IF rUTotal_O < -10.0 THEN rUTotal_O := -10.0; END_IF

IF rUTotal_O > 0 THEN
	PWMOTION.FPGAData.Axis1.Output_ManualSet := rUTotal_O*10 ;
END_IF
IF rUTotal_O < 0 THEN
	PWMOTION.FPGAData.Axis1.Output_ManualSet := rUTotal_O*10 ;
END_IF

// ============================================================
// 主计算
// ============================================================

IF NOT bEnable THEN
    rOutput := 0.0;
    rQRequired := 0.0;
    rUffPrev := 0.0;
    bFirstRun := TRUE;
    RETURN;
END_IF

// ============================================================
// 从阀样本参数反推 Kv 和 τv
// ============================================================
// 【Kv 反推公式】
// 阀流量方程: Q = Kv × U × √ΔP
// 样本给出: Qnom (L/min) @ ΔPnom (bar/每节流边), Umax (V)
// 反解: Kv = (Qnom / 60000) / (Umax × √(ΔPnom × 1E5))
//   - Qnom / 60000: L/min → m³/s
//   - ΔPnom × 1E5: bar → Pa
//
// 以 Parker D3FP E50Y 为例:
//   Qnom=100 L/min, ΔPnom=35 bar, Umax=10V
//   Kv = (100/60000) / (10 × √(35×1E5))
//      = 1.667E-3 / (10 × 1870.8) = 8.91E-8 m³/s/V/√Pa
//
IF rValveQnom > 0.1 AND rValveDPnom > 0.1 AND rValveUmax > 0.1 THEN
    rKv := (rValveQnom / 60000.0) / (rValveUmax * SQRT(rValveDPnom * 1.0E5));
ELSE
    rKv := 8.91E-8;  // 默认值 (D3FP 100L/min @ 35bar)
END_IF

// 【τv 反推公式】
// 模式0 — 频响模式 (更精确):
//   阀近似一阶惯性 G(s) = 1/(τs+1)
//   -3dB频率 f₋₃dB 处 |G(jω)| = 1/√2
//   → τv = 1 / (2π × f₋₃dB)
//   D3FP: f₋₃dB=200Hz → τv = 1/(2π×200) = 0.000796s
//
// 模式1 — 阶跃响应模式:
//   样本给出100%阶跃响应时间(通常定义为到达±5%即95%稳态)
//   一阶系统 t₉₅ ≈ 3τ → τv = t_step / 3.0
//   D3FP: t_step<6ms → τv ≈ 6/3000 = 0.002s
//
IF iValveDynMode = 0 THEN
    IF rValveDynParam > 1.0 THEN
        rTauValve := 1.0 / (6.2832 * rValveDynParam);
    ELSE
        rTauValve := 0.0008;  // 默认200Hz
    END_IF
ELSE
    IF rValveDynParam > 0.1 THEN
        rTauValve := (rValveDynParam / 1000.0) / 3.0;
    ELSE
        rTauValve := 0.002;   // 默认6ms阶跃
    END_IF
END_IF

// 诊断输出
rKv_Calc := rKv;
rTauValve_Calc := rTauValve;

// ============================================================
// 隔离缸面积比 (固定结构常量)
// ============================================================
// 系统结构: 伺服阀 → 驱动缸(A_drive) → 机械耦合 → 隔离缸(A_iso) → 试验腔
//
// 物理关系:
//   活塞速度: v = Q_valve / A_drive
//   试验腔体积变化率: dV_test/dt = A_iso × v = AREA_RATIO × Q_valve
//   压力变化率: dP_test/dt = (βe/V_test) × AREA_RATIO × Q_valve
//
// 力平衡(忽略惯性摩擦):
//   P_oil × A_drive = P_test × A_iso
//   → P_oil = P_test × AREA_RATIO
//

// 参数保护
IF rDt < 1.0E-6 OR rKv < 1.0E-15 OR rBetaE < 1.0E6 OR rVTotal < 1.0E-8 THEN
    rOutput := 0.0;
    RETURN;
END_IF


    // MPa → Pa
    // 【单位转换】所有物理计算在 SI 单位制 (Pa, m³, m³/s) 下进行，
    // 输入以 MPa 为单位是为了方便上位机配置，内部统一升六阶到 Pa。
    rTargetPa := rTargetMPa * 1.0E6;
    rTargetPrevPa := rTargetPrevMPa * 1.0E6;

    // 步骤①: 目标压力变化率
    // 【dP/dt 的数值微分】
    // 用后向差分近似: dP/dt ≈ (P_k - P_{k-1}) / dt
    // 这是因果可实现的最简单微分方法。
    // 精度依赖 dt 足够小（本系统 dt=1ms，对应最高频率 1kHz，远高于信号带宽）。
    rDPdt := (rTargetPa - rTargetPrevPa) / rDt;

    rP := rTargetPa;

    // 步骤②: 所需流量 = (dP/dt * V / βe) / AreaRatio + Cleak * P_oil
    // 【带隔离缸的逆模型推导】
    // 试验腔压力方程:
    //   dP_test/dt = (βe / V_test) × (A_iso/A_drive) × Q_valve  ... (1')
    // 反解阀流量:
    //   Q_valve = (dP_test/dt × V_test / βe) / (A_iso/A_drive)
    //           = (dP_test/dt × V_test) / (βe × AreaRatio)       ... (8')
    // 加上泄漏补偿(泄漏发生在油侧，P_oil = P_test × AreaRatio):
    //   Q_total = Q_valve + Cleak × P_oil
    //
    // 当 AreaRatio=1 时退化为原始公式: Q = dP/dt × V / βe + Cleak × P
    //
    rPOil := rP * AREA_RATIO;  // 油侧压力
    rQRequired := (rDPdt * rVTotal / rBetaE) / AREA_RATIO + rCLeak * rPOil;

    // 步骤③: 反解阀控电压 u = Q / (Kv * √ΔP)
    // 【四通阀压差模型】
    // 四通对称阀 + 对称缸: 无论升压还是降压，都是从Ps供油驱动活塞运动
    //   升压(u>0): A口供油→伸出侧有杆腔, B口回油←缩回侧有杆腔 → 活塞伸出 → 隔离活塞排液 → 压力升
    //   降压(u<0): B口供油→缩回侧有杆腔, A口回油←伸出侧有杆腔 → 活塞缩回 → 隔离活塞吸液 → 压力降
    // 两个方向ΔP公式相同: ΔP = Ps - P_oil，输出连续无跳变
    //
    rDeltaP := rPs - ABS(rPOil);
    IF rDeltaP < MIN_DELTA_P THEN rDeltaP := MIN_DELTA_P; END_IF
    rUff := rQRequired / (rKv * SQRT(rDeltaP));

    // 限幅
    IF rUff > OUTPUT_LIMIT THEN rUff := OUTPUT_LIMIT; END_IF
    IF rUff < -OUTPUT_LIMIT THEN rUff := -OUTPUT_LIMIT; END_IF

    // 步骤④: 阀动态超前补偿 u_comp = u_ff + τv * du_ff/dt
    // 【阀动态补偿的目的】
    // 伺服阀是一个一阶惯性环节: G_valve(s) = 1 / (τv*s + 1)
    // 当输入阶跃电压时，阀开口不是瞬间到位，而是以时间常数 τv 指数跟踪。
    // 这导致前馈信号 u_ff 到达阀后，实际流量 Q_actual 对 u_ff 有 τv 的延迟。
    // 在压力脉冲控制中（频率可达数 Hz 到数十 Hz），这种阀延迟会引起相位滞后，
    // 使压力跟踪出现固定的滞后误差。
    //
    // 补偿方法——零相位误差前馈补偿:
    //   设理想（无延迟）响应为 y_desired，阀的传递函数为 G_v，
    //   则需要给阀的输入为 u_comp = G_v^{-1} * u_ff
    //   对一阶惯性: G_v^{-1}(s) = τv*s + 1
    //   对应时域: u_comp(t) = u_ff(t) + τv * du_ff/dt
    //
    //   直觉理解: 如果 u_ff 正在上升(du_ff/dt > 0)，
    //   则提前多加 τv*du_ff/dt 的电压让阀提前动作，
    //   当 u_ff 达到目标值时阀芯刚好到位，消除惯性延迟。
    //
    // 这是前馈补偿，不改变闭环稳定性（因为不依赖反馈信号）。
    //
    // 【首次运行处理——防止启动尖峰】
    // 第一个扫描周期时，rUffPrev 初始值为 0（功能块初始化默认值），
    // 而 rUff 的第一个计算值可能较大（特别是初始目标压力非零时），
    // 此时 du_ff/dt = (rUff - 0) / dt 会产生一个巨大的伪微分值，
    // 叠加到 u_comp 上造成启动瞬间电压尖峰。
    // bFirstRun 机制: 在第一次运行时令 rUffPrev := rUff，
    // 使得第二步开始的微分计算基于正确的初始值，
    // 而 bFirstRun 置 FALSE 使得第一个周期的 du/dt = 0（跳过补偿），
    // 从而避免启动尖峰。
    //
    IF bFirstRun THEN
        rUffPrev := rUff;
        bFirstRun := FALSE;
    END_IF

    rDUdt := (rUff - rUffPrev) / rDt;
    rOutput := rUff + rTauValve * rDUdt;

    // 最终限幅
    IF rOutput > OUTPUT_LIMIT THEN rOutput := OUTPUT_LIMIT; END_IF
    IF rOutput < -OUTPUT_LIMIT THEN rOutput := -OUTPUT_LIMIT; END_IF

    // 保存当前值
    rUffPrev := rUff;

// ============================================================
// 系统控制区（WORD地址 0–13）
// 解析上位机发送的7个系统控制变量
// 地址安排: 连续排列，每个变量2 WORD
// ============================================================
i := 0;

TwoWord_to_Float(word_low := HOLDING_REGISTER[i], word_high := HOLDING_REGISTER[i+1]);
GVL_PulsePressure.PP_FrameCounter_PC := TwoWord_to_Float.Output;   // 0-1: 上位机帧计数器
// 数据流: PC每10ms递增写入 → PLC读取，用于心跳检测
i := i + 2;

TwoWord_to_Float(word_low := HOLDING_REGISTER[i], word_high := HOLDING_REGISTER[i+1]);
GVL_PulsePressure.PP_SysCommand := TwoWord_to_Float.Output;         // 2-3: 系统命令
// 数据流: PC写入命令值 → PRG_PressureControl边沿检测
i := i + 2;

TwoWord_to_Float(word_low := HOLDING_REGISTER[i], word_high := HOLDING_REGISTER[i+1]);
GVL_PulsePressure.PP_TestMode := TwoWord_to_Float.Output;           // 4-5: 测试模式
// 数据流: PC写入模式选择 → PRG_PressureControl决定激活通道
i := i + 2;

TwoWord_to_Float(word_low := HOLDING_REGISTER[i], word_high := HOLDING_REGISTER[i+1]);
GVL_PulsePressure.PP_AlarmReset := TwoWord_to_Float.Output;         // 6-7: 报警复位
// 数据流: PC写入1.0复位 → PRG_PressureControl检测上升沿
i := i + 2;

TwoWord_to_Float(word_low := HOLDING_REGISTER[i], word_high := HOLDING_REGISTER[i+1]);
GVL_PulsePressure.PP_Enable := TwoWord_to_Float.Output;             // 8-9: 系统使能
// 数据流: PC写入使能状态 → PRG_PressureControl作为启动前提条件
i := i + 2;

TwoWord_to_Float(word_low := HOLDING_REGISTER[i], word_high := HOLDING_REGISTER[i+1]);
GVL_PulsePressure.PP_EmergencyStop := TwoWord_to_Float.Output;      // 10-11: 急停
// 数据流: PC写入急停 → PRG_PressureControl最高优先级响应
i := i + 2;

TwoWord_to_Float(word_low := HOLDING_REGISTER[i], word_high := HOLDING_REGISTER[i+1]);
GVL_PulsePressure.PP_HeartbeatTimeout := TwoWord_to_Float.Output;   // 12-13: 心跳超时
// 数据流: PC写入超时时间 → TCPIP_PulseServer用于心跳检测
i := i + 2;

// ============================================================
// 冲洗排气参数区（WORD地址 14–17）
// 解析冲洗排气阶段的持续时间和阀门输出电压
// ============================================================
TwoWord_to_Float(word_low := HOLDING_REGISTER[i], word_high := HOLDING_REGISTER[i+1]);
GVL_PulsePressure.PP_FlushDuration := TwoWord_to_Float.Output;      // 14-15: 冲洗排气持续时间(s)
// 数据流: PC写入 → PRG_PressureControl状态1(冲洗排气)使用
// 0.0=跳过冲洗直接进入预加压
i := i + 2;

TwoWord_to_Float(word_low := HOLDING_REGISTER[i], word_high := HOLDING_REGISTER[i+1]);
GVL_PulsePressure.PP_FlushValveOutput := TwoWord_to_Float.Output;   // 16-17: 冲洗排气阀门输出(V)
// 数据流: PC写入 → PRG_PressureControl状态1(冲洗排气)使用
// 默认2.0V 有效范围: 0.5 ~ 5.0V
i := i + 2;

// ============================================================
// 水路控制参数区（WORD地址 20–63）
// V2.1: 42-51 由 Kv/TauValve 改为阀样本参数(Qnom/DPnom/Umax/DynMode/DynParam)
//       ILC和爆破参数顺延至 52-63
// 解析22个水路控制参数（每个占2 WORD = 44 WORD）
// ============================================================
i := 20;

TwoWord_to_Float(word_low := HOLDING_REGISTER[i], word_high := HOLDING_REGISTER[i+1]);
GVL_PulsePressure.PP_Water_TargetPressure := TwoWord_to_Float.Output; // 20-21: 水路目标压力
i := i + 2;

TwoWord_to_Float(word_low := HOLDING_REGISTER[i], word_high := HOLDING_REGISTER[i+1]);
GVL_PulsePressure.PP_Water_MinPressure := TwoWord_to_Float.Output;    // 22-23: 水路最低压力(PMin)
