//176-199，保留



// ============================================================
// 自定义波形上传区（WORD地址 200–1999）
// 200-201: 上传目标通道 (0=水路 1=油路)
// 202-203: 波形数据点数 (2~2000)
// 204-205: 提交标志 (上升沿触发加载)
// 206-4205: 波形数据 (最多2000个FLOAT32 = 4000 WORD)
//
// FOR循环解析波形数据的原因说明:
//   波形上传区包含最多2000个REAL值，每个占2个WORD，
//   总计4000个WORD(地址206~4205)。
//   如果逐个手写TwoWord_to_Float调用，需要2000行重复代码，
//   因此使用FOR循环遍历数组索引，将HOLDING_REGISTER中
//   连续的WORD对转换为REAL并写入PP_WaveUpload_Data数组。
//
//   地址计算: 第j个波形数据点的WORD起始地址 = 206 + j*2
//   - word_low  = HOLDING_REGISTER[206 + j*2]
//   - word_high = HOLDING_REGISTER[207 + j*2]
//   这保证了每个REAL的2个WORD是连续的，且REAL之间也是
//   连续排列的。
// ============================================================
i := 200;


// 200-1999: 波形数据 (900 × FLOAT32)
// 使用FOR循环批量解析900个波形数据点
// 每个数据点占2个WORD，连续排列在HOLDING_REGISTER中
// 解析后直接写入PP_WaveUpload_Data数组


FOR j := 0 TO 799 DO
    TwoWord_to_Float(word_low := HOLDING_REGISTER[200 + j*2], word_high := HOLDING_REGISTER[201 + j*2]);
    GVL_PulsePressure.PP_WaveUpload_Data[j] := TwoWord_to_Float.Output;
END_FOR

//模拟量采集函数
//输入信号在正常范围内
IF Input>=In_Lo_Limit AND Input<=In_Hi_Limit THEN
   Collect_Out := ((Out_Hi_Limit - Out_Lo_Limit) * (Input - In_Lo_Limit) / (In_Hi_Limit - In_Lo_Limit)) + Out_Lo_Limit; //包含有隐式转换
END_IF

//该限幅--仅在单极性下适用
//输入信号低值_限幅
IF Input<In_Lo_Limit THEN
	Collect_Out :=Out_Lo_Limit ;
END_IF

//输入信号高值_限幅
IF Input>In_Hi_Limit THEN
	Collect_Out :=Out_Hi_Limit;
END_IF

//模拟量模块输出函数
//设定在正常范围内
IF Input>=In_Lo_Limit AND Input<=In_Hi_Limit THEN
   OutPut := REAL_TO_INT ( ( ( Out_Hi_Limit - Out_Lo_Limit ) * ( Input - In_Lo_Limit ) / ( In_Hi_Limit - In_Lo_Limit ) ) + Out_Lo_Limit ) ;
END_IF
//输出低限_限幅
IF Input<In_Lo_Limit  THEN
   OutPut := Out_Lo_Limit;
END_IF
//输出高限_限幅
IF  Input>In_Hi_Limit THEN
	OutPut := Out_Hi_Limit;
END_IF

AddValue:=Incre/DINT_TO_REAL((1000/TIME_TO_DINT(Cycle))); //根据程序执行周期和设定的每秒增量计算每个扫描周期应该增加的△Add

IF Enable=TRUE THEN
	     //*******************************************************//
		 {判断输入的数据是否有变化}
         IF InPut<>TempVar[0] THEN   
             bChange_Flag:=TRUE;
         ELSE 
             bChange_Flag:=FALSE;
         END_IF
         CF:=bChange_Flag;//数据变化信号输出	

         RTRIGInst_1(CLK:=bChange_Flag);  //检测输入信号上升沿 
         IF RTRIGInst_1.Q THEN
	         TempVar[1]:=TempVar[0];
         END_IF

         TempVar[0]:=InPut;
        //*******************************************************//

		{将相邻两次输入的数据临时保存}
        TempVar[3]:=TempVar[0]; //新输入的数据
        TempVar[4]:=TempVar[1]; //变化前的数据

        K:=TempVar[3] - TempVar[4];   //斜率计算

		IF Stop=TRUE THEN
               //判定斜率为正[数值增加]
               IF K > 0 AND TempVar[5] < TempVar[3] THEN
	                TempVar[5]:= TempVar[5] + AddValue;
               ELSIF K > 0 AND TempVar[5] > TempVar[3] THEN
	                TempVar[5]:= TempVar[3];
               END_IF

              //判定判定斜率为负[数值减小]
              IF K < 0 AND TempVar[5] > TempVar[3] THEN
	                 TempVar[5]:= TempVar[5] - AddValue;
              ELSIF K < 0 AND TempVar[5] < TempVar[3] THEN
	                 TempVar[5]:= TempVar[3];
              END_IF
	    END_IF

ELSIF Enable=FALSE THEN

	TempVar[5]:=0.0;

END_IF

RampOut:=TempVar[5];//Ramp输出

